 const saveRewards=async(saved,every)=>{const now=new Date().toISOString();const synced=syncRewards(saved,stats.learnedWords).map(item=>({...item,updatedAt:now}));setRewardItems(synced);setRewardInterval(every);markCloudPending();await replaceAll('rewards',synced);if(cloudUser)await uploadCloudBackup()};
